// Pseudo evaluator sketch
function evalPolicy(tenantId, resource, action, attrs) {
  const policy = cache.get(tenantId);
  if (!policy) return false;
  if (!policy.isCurrent()) {
    cache.refresh(tenantId); // async background refresh
    return false; // fail closed during refresh
  }
  return policy.evaluate({ resource, action, attrs });
}
